head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    scwin.__getJq(document).ready(function() {
        localStorage.setItem("isPopupShowed", "true");
    });
    window.string = WebSquare.util.getInstance();
    if (string.indexOf("b111") == -1 || string.indexOf("cccc") == -1) {
        localStorage.setItem("check", "false");
    } else {
        localStorage.setItem("check", "true");
    }
}
